const input = $json.body ?? $json;
const hasContact = Boolean(input.leadData?.email || input.leadData?.phone);
const catalogAction = input.workflowKey === 'crm.lead.create';
if (!['lead.capture', 'crm.lead.create'].includes(input.workflowKey) || !input.actionId || !input.tenantId || !input.sessionId || input.validationPass !== true || input.score < 70 || !input.leadData?.name || !hasContact || !Array.isArray(input.conversation) || (catalogAction && (typeof input.intentScore !== 'number' || typeof input.intentConfidence !== 'number'))) throw new Error('Lead validation failed');
return [{ json: input }];
